-- iClub 9701 J11 production READ-ONLY gate: full 154+12 source versus generic publisher.
-- Safety-invariant TRUE = good. Publisher incompatibility is deliberately an expected block.
SELECT
(SELECT expected_skills=166 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS release_package_166_expected,
(SELECT theory_skills=154 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS theory_154,
(SELECT lab_skills=12 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS labs_12,
(SELECT AS_skills=91 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS AS_skills_91,
(SELECT P3_labs=6 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS Paper3_labs_6,
(SELECT P5_labs=6 FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS Paper5_labs_6,
(SELECT full_package_source_integrity FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS full_package_integrity,
(SELECT theory_trilingual_hash_ready FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS theory_trilingual_valid,
(SELECT lab_catalog_ready FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS labs_trilingual_valid,
(SELECT NOT generic_publisher_compatible FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS publisher_incompatibility_recognized,
(SELECT NOT release_validated FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS not_academically_released,
(SELECT NOT owner_approved_to_publish FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS owner_approval_missing,
(SELECT NOT student_beta_enabled FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS no_student_beta,
(SELECT library_hidden FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS library_hidden,
(SELECT core_off FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS program_closed,
(SELECT entry_off FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS entry_closed,
(SELECT recheck_off FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS recheck_closed,
(SELECT p1_off FROM private.iclub_exam_chemistry_j11_release_readiness_v1) AS P1_closed,
(SELECT state='draft' AND validated_at IS NULL FROM private.iclub_subject_library_releases WHERE subject_key='chemistry') AS release_still_draft,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_release_items_v1) AND (SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_release_items_v1) AND (SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_owner_release_items_v1) AS release_approvals_zero,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_entry_items_v1) AS entry_original_22,
(SELECT count(*)=154 FROM private.iclub_exam_chemistry_entry_review_v1 WHERE verdict='internal_ai_pass') AS entry_QA_154,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_recheck_items_v1) AS recheck_original_22,
(SELECT count(*)=154 FROM private.iclub_exam_chemistry_recheck_review_v1 WHERE verdict='internal_ai_pass') AS recheck_QA_154,
(SELECT count(*)=45 FROM private.iclub_exam_core_chemistry_p1_secure_drafts_v1) AS original_P1_45,
(SELECT count(*)=26 FROM private.iclub_exam_core_chemistry_p1_quarantine_v1) AS older_26_retained,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_attempts_v1) AS no_entry_sessions,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_attempts_v1) AS no_recheck_sessions,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_live_attempts_v1) AS no_chemistry_P1_sessions,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_beta_members_v1) AS no_chemistry_beta_members,
(SELECT count(*)=0 FROM private.iclub_subject_library_release_events WHERE subject_key='chemistry') AS no_published_library_events,
NOT has_function_privilege('anon','public.iclub_subject_library_publish_service_v1(text,text,text)','EXECUTE') AS publisher_anon_denied,
NOT has_function_privilege('authenticated','public.iclub_subject_library_publish_service_v1(text,text,text)','EXECUTE') AS publisher_auth_denied,
NOT has_function_privilege('anon','public.iclub_subject_library_hide_service_v1(text)','EXECUTE') AS hider_anon_denied,
NOT has_function_privilege('authenticated','public.iclub_subject_library_hide_service_v1(text)','EXECUTE') AS hider_auth_denied,
NOT has_table_privilege('anon','private.iclub_exam_chemistry_j11_release_readiness_v1','SELECT') AND NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_j11_release_readiness_v1','SELECT') AS j11_view_private,
(SELECT count(*)>=544 FROM private.exam_prep_sessions) AS math_sessions_intact,
(SELECT count(*)>=1979 FROM private.exam_prep_responses) AS math_responses_intact,
(SELECT count(*)>=502 FROM public.practice_attempts) AS practice_attempts_intact,
(SELECT count(*)>=4816 FROM public.practice_answers) AS practice_answers_intact,
(SELECT count(*)>=1 FROM private.iclub_exam_native_mcq_attempts_v1) AS econ_native_history_intact,
(SELECT count(*)>=2098 FROM public.user_subjects) AS user_subjects_intact;